const distritos = ["Miraflores", "San Isidro", "Surco", "La Molina", "San Borja"];
const categorias = [
  { slug: "gasfiteria", termino: "gasfitero" },
  { slug: "electricidad", termino: "electricista" },
  { slug: "pintura", termino: "pintor" },
  { slug: "carpinteria", termino: "carpintero" },
  { slug: "cerrajeria", termino: "cerrajero" },
];

const dia = new Date().getDay();
const categoria = categorias[dia % categorias.length];

return distritos.map((distrito) => ({
  json: {
    query: `${categoria.termino} en ${distrito}, Lima`,
    categoria: categoria.slug,
    distrito,
  },
}));

const details = $json.result || {};
const busqueda = $('Definir búsquedas').item.json;
const lugar = $('Dividir resultados').item.json;

return [{
  json: {
    tipo: "PROFESIONAL",
    nombre: details.name || lugar.name || null,
    telefono: details.formatted_phone_number || null,
    direccion: details.formatted_address || lugar.formatted_address || null,
    categoria: busqueda.categoria,
    distrito: busqueda.distrito,
    fuente: "google_places",
    fuenteRef: lugar.place_id,
  },
}];
